#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int maxCoins(vector<int>& piles) {
        sort(piles.begin(), piles.end());
        int res = 0, n = piles.size() / 3;
        for (int i = piles.size() - 2; i >= n; i -= 2)
            res += piles[i];
        return res;
    }
};
